var WILDFIRE_MARK = refinements((r, rank) => {
  const WILDFIRE_TEAM = new Buff({
    name: `Wildfire Mark: Blazing Starfire${rank} (team)`,
    duration: 60 * 30,
    stats: [[
      18,
      [24, 30, 36, 42, 48][r],
      192
      /* Attribute.Fusion */
    ]]
  });
  const WILDFIRE_EXTENDED = new Buff({});
  const WILDFIRE_LIB_DMG = new Buff({
    name: `Wildfire Mark: Blazing Starfire${rank}`,
    duration: 60 * 6,
    stats: [[
      18,
      [24, 30, 36, 42, 48][r],
      16384
      /* Type.Liberation */
    ]],
    updateDebuffs: () => {
      if (!isType(
        8192
        /* Type.Heavy */
      ) || isHeld(WILDFIRE_EXTENDED))
        return;
      extendCurrent(WILDFIRE_LIB_DMG, 60 * 4);
      applyCurrent(WILDFIRE_EXTENDED, 1);
      applyTeam(WILDFIRE_TEAM, 1);
    }
  });
  return new Weapon({
    weaponType: 1,
    name: `Wildfire Mark${rank}`,
    stats: [[0, 587.5], [10, 48.6], [6, [12, 15, 18, 21, 24][r]]],
    grants: [{ on: onCast(
      5,
      4
      /* Cast.Liberation */
    ), buff: WILDFIRE_LIB_DMG }],
    // a fresh grant can be extended again
    updateBuffs: () => {
      if (casting(
        5
        /* Cast.Intro */
      ) || casting(
        4
        /* Cast.Liberation */
      ))
        revokeCurrent(WILDFIRE_EXTENDED);
    }
  });
});
var JINGRAN_SIG = refinements((r, rank) => {
  const NATURES_ORDER = new Buff({
    name: `Thousandfold Deliverance: Nature's Order${rank}`,
    maxStacks: 6,
    duration: 60 * 7,
    lostOnSwap: true,
    stats: [[10, [4, 5, 6, 7, 8][r]]],
    perStack: true,
    applyStats: () => {
      if (frozenStacks() >= 6)
        addStat(
          9,
          [12, 15, 18, 21, 24][r],
          8192
          /* Type.Heavy */
        );
    }
  });
  const CRADLE_SPENT = new Buff({
    name: `Thousandfold Deliverance: Cradle of Life${rank} (spent)`,
    maxStacks: 2,
    duration: 60 * 2,
    stats: [[
      23,
      [15, 17.5, 20, 22.5, 25][r],
      8192
      /* Type.Heavy */
    ]],
    perStack: true
  });
  const CRADLE_OF_LIFE = new Buff({
    name: `Thousandfold Deliverance: Cradle of Life${rank}`,
    maxStacks: 6,
    duration: 60 * 7,
    lostOnSwap: true,
    updateBuffs: () => {
      if (!casting(
        2
        /* Cast.Heavy */
      ))
        return;
      const spent = Math.min(frozenStacks(), 2);
      if (!spent)
        return;
      removeStack(CRADLE_OF_LIFE, spent);
      setStacksSelf(CRADLE_SPENT, spent);
    }
  });
  return new Weapon({
    weaponType: 1,
    name: `Thousandfold Deliverance${rank}`,
    stats: [[0, 412.5], [7, 72.225], [18, [12, 15, 18, 21, 24][r]]],
    // two separate triggers, so his Intro — which also shields — pays both and stacks twice
    grants: [
      { on: onCast(
        5
        /* Cast.Intro */
      ), buff: NATURES_ORDER },
      { on: onCast(
        5
        /* Cast.Intro */
      ), buff: CRADLE_OF_LIFE },
      { on: onApplied(SHIELD), buff: NATURES_ORDER, stacks: () => applied2(SHIELD) },
      { on: onApplied(SHIELD), buff: CRADLE_OF_LIFE, stacks: () => applied2(SHIELD) }
    ]
  });
});
