function hp() {
  const base = getStat(
    1
    /* Stat.BaseHp */
  );
  return base + getStat(
    7
    /* Stat.BonusHp */
  ) / 100 * base + getStat(
    4
    /* Stat.FlatHp */
  );
}
function def() {
  const base = getStat(
    2
    /* Stat.BaseDef */
  );
  return base + getStat(
    8
    /* Stat.BonusDef */
  ) / 100 * base + getStat(
    5
    /* Stat.FlatDef */
  );
}
function hpSteps() {
  return Math.floor(Math.min(hp(), 5e4) / 1e3);
}
