function erosionPulls(every, count) {
  const pull = { mv: 13633, updateDebuffs: () => deniaLays(2) };
  const out = [];
  for (let k = 0; k < count - 1; k++)
    out.push({ hitFrame: 158 + every * k, ...pull });
  out.push({
    hitFrame: 158 + every * (count - 1),
    mv: 13633,
    updateDebuffs: () => {
      deniaLays(2);
      revokeTeam(EROSION_SET);
    }
  });
  return out;
}
