var CAMELLYA_RESONATOR = new Resonator({
  name: "Camellya",
  matrix: matrix("Camellya", 25),
  talent: CAMELLYA_TALENTS,
  inherent1: SEEDBED,
  inherent2: EPIPHYTE,
  element: 384,
  weapon: 0,
  tuneBreak: tuneBreak(89, [0, 91], [0, 70], SWORD_BREAK),
  color: "#891c2b",
  intro: Intro35,
  outro: () => isHeld(TWINING) ? OutroEphemeral : Outro37,
  // Blossom Mode replaces Basic Attack with Vining Waltz, which can be used in mid-air too
  swapIn: () => isHeld(BLOSSOM_MODE) ? VW1 : BA139,
  swapInAir: () => isHeld(BLOSSOM_MODE) ? VW1 : MA45,
  maxEnergy: 12500,
  forteScale: [0.01, 1, 1, 1, 1],
  maxForte1: 1e4,
  // any gauge-spending cast of hers is a Crimson Pistil consumption, counted as the cast spends it
  updateBuffs: () => {
    const spent = currentCast().castForte[0];
    if (spent >= 0)
      return;
    const before = forte1();
    const buds = Math.max(0, Math.floor((1e4 - Math.max(0, before + spent)) / 1e3) - Math.floor((1e4 - before) / 1e3));
    if (buds > 0 && !isHeld(BUDDING_MODE))
      applyCurrent(CRIMSON_BUD, buds);
    applyCurrent(CONSUME_CRIMSON_PISTIL, 1 + buds);
    if (buds > 0)
      addGain({ concerto: 400 * buds });
  },
  stats: [[1, 10325], [0, 450], [2, 1161.109]]
});
