function skAction(id, def2) {
  return new Action(id, { element: 320, scaling: 0, ...def2 });
}
function stellarealm(stage, next, stats) {
  const self2 = new Buff({
    name: `Shorekeeper: ${stage} Stellarealm`,
    duration: 60 * 30,
    stats,
    updateBuffs: () => {
      if (!casting(
        6
        /* Cast.Outro */
      ))
        return;
      if (next) {
        revokeTeam(self2);
        applyTeam(next(), 1);
      } else
        applyTeam(self2, 1);
    }
  });
  return self2;
}
